import{_ as o,r as s,o as p,c,e as a,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const x=JSON.parse('{"title":"Import Export Model - October CMS - 4.x","titleTemplate":false,"description":"Learn how to customize the import and export process.","frontmatter":{"subtitle":"Learn how to customize the import and export process."},"headers":[{"level":2,"title":"Import Model","slug":"import-model","link":"#import-model","children":[{"level":3,"title":"Importing with PHP","slug":"importing-with-php","link":"#importing-with-php","children":[]}]},{"level":2,"title":"Export Model","slug":"export-model","link":"#export-model","children":[{"level":3,"title":"Exporting with PHP","slug":"exporting-with-php","link":"#exporting-with-php","children":[]}]},{"level":2,"title":"File Attachments","slug":"file-attachments","link":"#file-attachments","children":[{"level":3,"title":"Exporting File Attachments","slug":"exporting-file-attachments","link":"#exporting-file-attachments","children":[]},{"level":3,"title":"Importing File Attachments","slug":"importing-file-attachments","link":"#importing-file-attachments","children":[]}]},{"level":2,"title":"Custom Options","slug":"custom-options","link":"#custom-options","children":[]}],"relativePath":"4.x/extend/importexport/importexport-model.md","filePath":"4.x/extend/importexport/importexport-model.md"}'),r={name:"4.x/extend/importexport/importexport-model.md"};function u(d,n,k,h,m,g){const t=s("pre-heading"),e=s("post-heading");return p(),c("div",null,[a(t),n[0]||(n[0]=l("h1",null,"Import Export Model",-1)),a(e),n[1]||(n[1]=i(`<p>Import and Export models define the logic used when processing the import or export action, extending the <code>Backend\\Models\\ImportModel</code> and <code>Backend\\Models\\ExportModel</code> models respectively. These models are designed to be used with the <a href="./importexport-controller.html">Import Export Controller</a>, however, it is possible to work with them directly in PHP.</p><h2 id="import-model"><a href="#import-model" class="header-anchor">#</a> Import Model</h2><p>For importing data you should create a dedicated model for this process which extends the <code>Backend\\Models\\ImportModel</code> class. Here is an example class definition:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">SubscriberImport</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>ImportModel</span>
<span class="token punctuation">{</span>
    <span class="token comment">/**
     * @var array rules to be applied to the data.
     */</span>
    <span class="token keyword">public</span> <span class="token variable">$rules</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">importData</span><span class="token punctuation">(</span><span class="token variable">$results</span><span class="token punctuation">,</span> <span class="token variable">$sessionKey</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$results</span> <span class="token keyword">as</span> <span class="token variable">$row</span> <span class="token operator">=&gt;</span> <span class="token variable">$data</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>

            <span class="token keyword">try</span> <span class="token punctuation">{</span>
                <span class="token variable">$subscriber</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Subscriber</span><span class="token punctuation">;</span>
                <span class="token variable">$subscriber</span><span class="token operator">-&gt;</span><span class="token function">fill</span><span class="token punctuation">(</span><span class="token variable">$data</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
                <span class="token variable">$subscriber</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

                <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">logCreated</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
            <span class="token punctuation">}</span>
            <span class="token keyword">catch</span> <span class="token punctuation">(</span><span class="token class-name">Exception</span> <span class="token variable">$ex</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
                <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">logError</span><span class="token punctuation">(</span><span class="token variable">$row</span><span class="token punctuation">,</span> <span class="token variable">$ex</span><span class="token operator">-&gt;</span><span class="token function">getMessage</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
            <span class="token punctuation">}</span>

        <span class="token punctuation">}</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The class must define a method called <code>importData</code> used for processing the imported data. The first parameter <code>$results</code> will contain an array containing the data to import. The second parameter <code>$sessionKey</code> will contain the session key used for the request.</p><div class="table"><table tabindex="0"><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>logUpdated()</code></td><td>Called when a record is updated.</td></tr><tr><td><code>logCreated()</code></td><td>Called when a record is created.</td></tr><tr><td><code>logError(rowIndex, message)</code></td><td>Called when there is a problem with importing the record.</td></tr><tr><td><code>logWarning(rowIndex, message)</code></td><td>Used to provide a soft warning, like modifying a value.</td></tr><tr><td><code>logSkipped(rowIndex, message)</code></td><td>Used when the entire row of data was not imported (skipped).</td></tr></tbody></table></div><h3 id="importing-with-php"><a href="#importing-with-php" class="header-anchor">#</a> Importing with PHP</h3><p>Use the <code>importFile</code> method process an import manually from a local file stored on the disk.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$importModel</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">MyImportClass</span><span class="token punctuation">;</span>

<span class="token variable">$importModel</span><span class="token operator">-&gt;</span><span class="token property">file_format</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;json&#39;</span><span class="token punctuation">;</span>

<span class="token variable">$importModel</span><span class="token operator">-&gt;</span><span class="token function">importFile</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;/path/to/import/file.json&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>If the file is coming from an uploaded file use the <code>Input</code> facade to access the local path.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$importModel</span><span class="token operator">-&gt;</span><span class="token function">importFile</span><span class="token punctuation">(</span>
    <span class="token class-name static-context">Input</span><span class="token operator">::</span><span class="token function">file</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">getRealPath</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="export-model"><a href="#export-model" class="header-anchor">#</a> Export Model</h2><p>For exporting data you should create a dedicated model which extends the <code>Backend\\Models\\ExportModel</code> class. Here is an example:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">SubscriberExport</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>ExportModel</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">exportData</span><span class="token punctuation">(</span><span class="token variable">$columns</span><span class="token punctuation">,</span> <span class="token variable">$sessionKey</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token variable">$subscribers</span> <span class="token operator">=</span> <span class="token class-name static-context">Subscriber</span><span class="token operator">::</span><span class="token function">all</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

        <span class="token variable">$subscribers</span><span class="token operator">-&gt;</span><span class="token function">each</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$subscriber</span><span class="token punctuation">)</span> <span class="token keyword">use</span> <span class="token punctuation">(</span><span class="token variable">$columns</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token variable">$subscriber</span><span class="token operator">-&gt;</span><span class="token function">addVisible</span><span class="token punctuation">(</span><span class="token variable">$columns</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

        <span class="token keyword">return</span> <span class="token variable">$subscribers</span><span class="token operator">-&gt;</span><span class="token function">toArray</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The class must define a method called <code>exportData</code> used for returning the export data. The first parameter <code>$columns</code> is an array of column names to export. The second parameter <code>$sessionKey</code> will contain the session key used for the request.</p><h3 id="exporting-with-php"><a href="#exporting-with-php" class="header-anchor">#</a> Exporting with PHP</h3><p>Use the <code>exportDownload</code> method to process an export manually and return a download response.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$exportColumns</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;title&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>

<span class="token variable">$exportModel</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">MyExportClass</span><span class="token punctuation">;</span>

<span class="token variable">$exportModel</span><span class="token operator">-&gt;</span><span class="token property">file_format</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;json&#39;</span><span class="token punctuation">;</span>

<span class="token keyword">return</span> <span class="token variable">$exportModel</span><span class="token operator">-&gt;</span><span class="token function">exportDownload</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;myexportfile.json&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;columns&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$exportColumns</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="file-attachments"><a href="#file-attachments" class="header-anchor">#</a> File Attachments</h2><p>Models with file attachment relations (<code>attachOne</code> and <code>attachMany</code>) can include file references in the import data. When exporting, file attachments are exported as relative file paths. When importing, these paths are resolved to local files and attached to the record.</p><h3 id="exporting-file-attachments"><a href="#exporting-file-attachments" class="header-anchor">#</a> Exporting File Attachments</h3><p>When exporting records that have file attachments, the export will automatically produce a <strong>ZIP archive</strong> instead of a plain JSON or CSV file. The ZIP contains the data file (<code>data.json</code> or <code>data.csv</code>) along with a <code>files/</code> directory containing the attachment files.</p><pre class="dir-container"><code><p>├── <code>export.zip</code>
|   ├── data.json
|   └── files
|       ├── hero.jpg
|       └── photo1.jpg</p>
</code></pre><p>In the data file, file attachment fields are stored as relative paths pointing to the files inside the archive.</p><div class="language-json extra-class"><pre class="language-json"><code><span class="token punctuation">[</span>
    <span class="token punctuation">{</span>
        <span class="token property">&quot;title&quot;</span><span class="token operator">:</span> <span class="token string">&quot;My Post&quot;</span><span class="token punctuation">,</span>
        <span class="token property">&quot;featured_image&quot;</span><span class="token operator">:</span> <span class="token string">&quot;files/hero.jpg&quot;</span><span class="token punctuation">,</span>
        <span class="token property">&quot;gallery&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token string">&quot;files/photo1.jpg&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;files/photo2.jpg&quot;</span><span class="token punctuation">]</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">]</span>
</code></pre></div><p>If no file attachments are included in the export, a standard JSON or CSV file is produced instead.</p><h3 id="importing-file-attachments"><a href="#importing-file-attachments" class="header-anchor">#</a> Importing File Attachments</h3><p>When importing, file attachment fields can reference files from two sources.</p><p><strong>ZIP Archive</strong> — Upload the exported ZIP file directly. File paths starting with <code>files/</code> are resolved from the archive contents.</p><p><strong>Media Library</strong> — Reference files already in the media library by their media-relative path. For example, if a file exists at <code>storage/app/media/photos/hero.jpg</code>, use <code>photos/hero.jpg</code> as the path.</p><div class="language-json extra-class"><pre class="language-json"><code><span class="token punctuation">[</span>
    <span class="token punctuation">{</span>
        <span class="token property">&quot;title&quot;</span><span class="token operator">:</span> <span class="token string">&quot;My Post&quot;</span><span class="token punctuation">,</span>
        <span class="token property">&quot;featured_image&quot;</span><span class="token operator">:</span> <span class="token string">&quot;photos/hero.jpg&quot;</span><span class="token punctuation">,</span>
        <span class="token property">&quot;gallery&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token string">&quot;photos/photo1.jpg&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;photos/photo2.jpg&quot;</span><span class="token punctuation">]</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">]</span>
</code></pre></div><p>For <code>attachOne</code> relations, the value should be a single path string. For <code>attachMany</code> relations, the value should be an array of path strings.</p><h2 id="custom-options"><a href="#custom-options" class="header-anchor">#</a> Custom Options</h2><p>Both import and export forms support custom options that can be introduced using form fields, defined in the <strong>form</strong> option in the import or export configuration respectively. These values are then passed to the Import / Export model and are available during processing.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># config_import_export.yaml</span>
<span class="token key atrule">import</span><span class="token punctuation">:</span>
    <span class="token comment"># ...</span>
    <span class="token key atrule">form</span><span class="token punctuation">:</span> $/acme/campaign/models/subscriberimport/fields.yaml

<span class="token key atrule">export</span><span class="token punctuation">:</span>
    <span class="token comment"># ...</span>
    <span class="token key atrule">form</span><span class="token punctuation">:</span> $/acme/campaign/models/subscriberexport/fields.yaml
</code></pre></div><p>The form fields specified will appear on the import/export page. Here is an example <code>fields.yaml</code> file contents:</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># fields.yaml</span>
<span class="token key atrule">fields</span><span class="token punctuation">:</span>

    <span class="token key atrule">auto_create_lists</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Automatically create lists
        <span class="token key atrule">type</span><span class="token punctuation">:</span> checkbox
        <span class="token key atrule">default</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
</code></pre></div><p>The value of the form field above called <strong>auto_create_lists</strong> can be accessed using <code>$this-&gt;auto_create_lists</code> inside the <code>importData</code> method of the import model. If this were the export model, the value would be available inside the <code>exportData</code> method instead.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">SubscriberImport</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>ImportModel</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">importData</span><span class="token punctuation">(</span><span class="token variable">$results</span><span class="token punctuation">,</span> <span class="token variable">$sessionKey</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">auto_create_lists</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token comment">// Do something</span>
        <span class="token punctuation">}</span>

        <span class="token comment">// ...</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div>`,39))])}const b=o(r,[["render",u]]);export{x as __pageData,b as default};
